                 <div style="font-size:11px;color:var(--text-muted);margin-bottom:4px;">MQTT 地址</div>
                 <strong style="font-size:13px;">huijian.local:2022</strong>
             </div>
             <div>
                 <div style="font-size:11px;color:var(--text-muted);margin-bottom:4px;">用户名 / 密码</div>
                 <strong style="font-size:13px;">huijian / huijian2022</strong>
             </div>
         </div>
         <div class="info-box">
             <h3>LoRa 网关配置说明</h3>
             <p>
                 Broker: <code>huijian.local</code>（mDNS）或 HA 的 IP 地址<br>
                 端口: <code>2022</code> | 用户名: <code>huijian</code> | 密码: <code>huijian2022</code><br>
                 网关上电后自动发现，无需手动填写 SN
             </p>
         </div>
     </div>

     <div class="card" id="updateCard" style="display:none;">
         <div class="card-title">版本更新</div>
         <div id="updateContent"></div>
     </div>

     <div class="footer">
         <p>慧尖 LoRa 网关一体化插件 <span id="footerVersion">v1.1.9</span></p>
     </div>

     <script>
-        let CURRENT_VERSION = '1.1.9';
+        let CURRENT_VERSION = '1.2.0';
         const DOMAIN = 'window_controller_gateway';

         // ========== 初始化 ==========
         async function init() {
             try {
                 const verResp = await fetch('/api/version');
                 if (verResp.ok) {
                     const verData = await verResp.json();
                     CURRENT_VERSION = verData.addon_version || CURRENT_VERSION;
                     document.getElementById('addonVersion').textContent = 'v' + CURRENT_VERSION;
                     document.getElementById('footerVersion').textContent = 'v' + CURRENT_VERSION;
                 }
             } catch (e) { console.log('版本获取失败:', e); }
             await refreshAll();
         }

         // ========== 刷新所有 ==========
         async function refreshAll() {
             await checkServiceStatus();
             await loadGateways();
         }

         // ========== 检查服务状态 ==========
         async function checkServiceStatus() {
             // 1. MQTT Broker 状态 — nginx 直接返回，不依赖 HA API
             try {
                 const resp = await fetch('/api/status');
                 if (resp.ok) {
                     const data = await resp.json();
                     if (data.status === 'running') {
                         setStatusDot('mqttStatus', 'ok', '运行中');
                     } else {
                         setStatusDot('mqttStatus', 'err', '已停止');
                     }
                 } else {
                     setStatusDot('mqttStatus', 'err', 'HTTP ' + resp.status);
                 }
             } catch (e) {
                 setStatusDot('mqttStatus', 'err', '无法连接');
             }
             // 2. 网关集成检测
             try {
                 const resp = await haApi('/config/config_entries/entry?domain=' + DOMAIN);
                 if (!resp.ok) {
                     setStatusDot('integrationStatus', 'err', resp.status === 401 ? '认证失败' : 'HTTP ' + resp.status);
                 } else {
                     const entries = await resp.json();
                     setStatusDot('integrationStatus', entries && entries.length > 0 ? 'ok' : 'warn',
                         entries && entries.length > 0 ? '已安装' : '未安装');
                 }
             } catch (e) {
                 setStatusDot('integrationStatus', 'err', '代理失败');
             }
             // 3. HA MQTT 集成检测
             try {
                 const resp = await haApi('/config/config_entries/entry?domain=mqtt');
                 if (!resp.ok) {
                     setStatusDot('haMqttStatus', 'err', resp.status === 401 ? '认证失败' : 'HTTP ' + resp.status);
                 } else {
                     const entries = await resp.json();
                     setStatusDot('haMqttStatus', entries && entries.length > 0 ? 'ok' : 'warn',
                         entries && entries.length > 0 ? '已配置' : '未配置');
                 }
             } catch (e) {
                 setStatusDot('haMqttStatus', 'err', '代理失败');
             }
         }

         function setStatusDot(elementId, status, text) {
             const el = document.getElementById(elementId);
             el.textContent = text;
             el.parentElement.querySelector('.dot').className = 'dot dot-' + status;
         }

         // ========== HA API 调用 ==========
         async function haApi(path, method = 'GET', body = null) {
             const opts = { method, headers: { 'Content-Type': 'application/json' } };
             if (body) opts.body = JSON.stringify(body);
             return await fetch('/api/ha/' + path, opts);
         }

         // ========== 加载网关列表 ==========
         async function loadGateways() {
             const container = document.getElementById('gatewayContainer');
             try {
                 const resp = await haApi('/config/config_entries/entry?domain=' + DOMAIN);
                 if (!resp.ok) throw new Error('HA API ' + resp.status);
                 const entries = await resp.json();
                 if (!entries || entries.length === 0) {
                     container.innerHTML = '<div class="empty-state"><div class="icon">📡</div><p>暂无网关</p><p class="hint">LoRa 网关上电后自动发现，或手动添加集成</p></div>';
                     return;
                 }
                 let html = '';
                 for (const entry of entries) {
                     const gwSn = entry.data.gateway_sn || '未知';
                     const gwName = entry.title || '慧尖网关';
                     html += renderGateway(gwName, gwSn, entry.entry_id);
                 }
                 container.innerHTML = html;
                 for (const entry of entries) {
                     await loadGatewayDevices(entry.entry_id, entry.data.gateway_sn);
                 }
             } catch (e) {
                 container.innerHTML = '<div class="empty-state"><div class="icon">📡</div><p>无法连接 HA API</p><p class="hint">请确保通过 HA 侧边栏访问</p></div><div class="info-box"><h3>使用说明</h3><p>1. LoRa 网关上电后会自动发现<br>2. 在网关设备上点击「配对」按钮添加子设备<br>3. 在 HA 设备页面控制子设备</p></div>';
             }
         }

         function renderGateway(name, sn, entryId) {
             const safeName = escapeHtml(name);
             const safeSn = escapeHtml(sn);
             const safeEntryId = escapeHtml(entryId);
             return '<div class="gateway-item" id="gw-' + safeEntryId + '">' +
                 '<div class="gateway-header"><div>' +
                 '<span class="gateway-name">' + safeName + '</span>' +
                 '<span class="gateway-sn">SN: ' + safeSn + '</span>' +
                 '</div><div>' +
                 '<span class="badge badge-info" id="gw-status-' + safeEntryId + '">检测中</span>' +
                 '<button class="btn btn-success btn-sm" onclick="startPairing(\'' + safeEntryId + '\',\'' + safeSn + '\')" style="margin-left:8px;">配对</button>' +
                 '</div></div>' +
                 '<div class="device-list" id="devices-' + safeEntryId + '"><div class="loading"><div class="spinner" style="width:16px;height:16px;"></div></div></div>' +
                 '</div>';
         }

         async function loadGatewayDevices(entryId, gatewaySn) {
             const deviceListEl = document.getElementById('devices-' + entryId);
             const statusEl = document.getElementById('gw-status-' + entryId);
             if (!deviceListEl) return;
             try {
                 const resp = await haApi('/config/device_registry?config_entry_id=' + entryId);
                 if (!resp.ok) throw new Error('HA API ' + resp.status);
                 const devices = await resp.json();
                 if (!devices || devices.length === 0) {
                     deviceListEl.innerHTML = '<p style="font-size:12px;color:var(--text-muted);padding:8px;">暂无子设备，点击「配对」按钮添加</p>';
                     updateGatewayStatus(statusEl, 'offline');
                     return;
                 }
                 let subDevices = [];
                 for (const dev of devices) {
                     if (dev.via_device_id) subDevices.push(dev);
                 }
                 try {
                     const stateResp = await haApi('/states');
                     if (!stateResp.ok) throw new Error('HA API ' + stateResp.status);
                     const states = await stateResp.json();
                     const snSuffix = gatewaySn.slice(-6).toLowerCase();
                     const gwSensor = states.find(s =>
                         s.entity_id.includes('binary_sensor') &&
                         s.entity_id.toLowerCase().includes(snSuffix) &&
                         s.entity_id.includes('online')
                     );
                     updateGatewayStatus(statusEl, gwSensor ? (gwSensor.state === 'on' ? 'online' : 'offline') : 'unknown');
                     if (subDevices.length === 0) {
                         deviceListEl.innerHTML = '<p style="font-size:12px;color:var(--text-muted);padding:8px;">暂无子设备，点击「配对」按钮添加</p>';
                         return;
                     }
                     let html = '';
                     for (const dev of subDevices) html += renderDevice(dev, entryId, states);
                     deviceListEl.innerHTML = html;
                     for (const dev of subDevices) loadDeviceState(dev, states);
                 } catch (e) {
                     updateGatewayStatus(statusEl, 'unknown');
                     if (subDevices.length === 0) {
                         deviceListEl.innerHTML = '<p style="font-size:12px;color:var(--text-muted);padding:8px;">暂无子设备，点击「配对」按钮添加</p>';
                         return;
                     }
                     let html = '';
                     for (const dev of subDevices) html += renderDevice(dev, entryId, []);
                     deviceListEl.innerHTML = html;
                 }
             } catch (e) {
                 deviceListEl.innerHTML = '<p style="font-size:12px;color:var(--red);">加载设备失败: ' + escapeHtml(e.message) + '</p>';
             }
         }

         function updateGatewayStatus(el, status) {
             if (status === 'online') { el.className = 'badge badge-ok'; el.textContent = '在线'; }
             else if (status === 'pairing') { el.className = 'badge badge-warn'; el.textContent = '配对中'; }
             else if (status === 'offline') { el.className = 'badge badge-err'; el.textContent = '离线'; }
             else { el.className = 'badge badge-gray'; el.textContent = '未知'; }
         }

         function renderDevice(dev, entryId, states) {
             const devName = dev.name_by_user || dev.name || '未命名设备';
             const devId = dev.id;
             let sn = '未知';
             if (dev.identifiers && dev.identifiers.length > 0) {
                 const ident = dev.identifiers[0];
                 if (Array.isArray(ident) && ident.length > 1) sn = ident[1];
             }
             const supportsWindLock = sn.startsWith('5005');
             const snSuffix = sn !== '未知' ? sn.slice(-6).toLowerCase() : '';
             const coverEntity = states.find(s =>
                 s.entity_id.startsWith('cover.') && s.entity_id.toLowerCase().includes(snSuffix)
             );
             const currentPos = coverEntity ? (coverEntity.attributes.current_position || 0) : 0;
             const safeName = escapeHtml(devName);
             const safeSn = escapeHtml(sn);
             const safeDevId = escapeHtml(devId);
             const safeEntryId = escapeHtml(entryId);
             let controls = '<div class="device-controls">' +
                 '<button class="btn btn-success btn-sm" onclick="controlDevice(\'' + safeDevId + '\',\'open\',\'' + safeEntryId + '\')">开</button>' +
                 '<button class="btn btn-danger btn-sm" onclick="controlDevice(\'' + safeDevId + '\',\'close\',\'' + safeEntryId + '\')">关</button>' +
                 '<button class="btn btn-warn btn-sm" onclick="controlDevice(\'' + safeDevId + '\',\'stop\',\'' + safeEntryId + '\')">停</button>' +
                 '<input type="range" class="position-slider" min="0" max="100" value="' + currentPos + '"' +
                 ' oninput="this.nextElementSibling.textContent=this.value+\'%\'"' +
                 ' onchange="controlDevicePosition(\'' + safeDevId + '\', this.value, \'' + safeEntryId + '\')">' +
                 '<span style="font-size:11px;min-width:30px;">' + currentPos + '%</span></div>';
             if (supportsWindLock) {
                 controls += '<div class="device-controls" style="margin-top:4px;">' +
                     '<button class="btn btn-sm" style="background:#607d8b;color:white;" onclick="controlDevice(\'' + safeDevId + '\',\'wind_lock_tilt\',\'' + safeEntryId + '\')">内倒</button>' +
                     '<button class="btn btn-sm" style="background:#78909c;color:white;" onclick="controlDevice(\'' + safeDevId + '\',\'wind_lock_flat\',\'' + safeEntryId + '\')">平开</button>' +
                     '</div>';
             }
             return '<div class="device-item" id="dev-' + safeDevId + '">' +
                 '<div class="device-info"><div class="device-name">' + safeName + '</div>' +
                 '<div class="device-sn">SN: ' + safeSn + '</div>' +
                 '<div class="device-status" id="dev-state-' + safeDevId + '">状态: 加载中</div></div>' +
                 controls + '</div>';
         }

         function loadDeviceState(dev, states) {
             const stateEl = document.getElementById('dev-state-' + dev.id);
             if (!stateEl) return;
             try {
                 let sn = '';
                 if (dev.identifiers && dev.identifiers.length > 0) {
                     const ident = dev.identifiers[0];
                     if (Array.isArray(ident) && ident.length > 1) sn = ident[1];
                 }
                 const snSuffix = sn.slice(-6).toLowerCase();
                 const coverEntity = states.find(s =>
                     s.entity_id.startsWith('cover.') && s.entity_id.toLowerCase().includes(snSuffix)
                 );
                 if (coverEntity) {
                     const pos = coverEntity.attributes.current_position;
                     const state = coverEntity.state;
                     let statusText;
                     if (state === 'open') statusText = '打开';
                     else if (state === 'closed' || state === 'close') statusText = '关闭';
                     else if (state === 'opening') statusText = '正在打开';
                     else if (state === 'closing') statusText = '正在关闭';
                     else statusText = state;
                     let attrs = '';
                     if (pos !== undefined) attrs += ' | 位置: ' + pos + '%';
                     if (coverEntity.attributes.voltage) attrs += ' | 电压: ' + coverEntity.attributes.voltage + 'V';
                     stateEl.textContent = '状态: ' + statusText + attrs;
                     const slider = document.querySelector('#dev-' + dev.id + ' .position-slider');
                     if (slider && pos !== undefined) {
                         slider.value = pos;
                         slider.nextElementSibling.textContent = pos + '%';
                     }
                     return;
                 }
                 stateEl.textContent = '状态: 无数据';
             } catch (e) {
                 stateEl.textContent = '状态: 加载失败';
             }
         }

         async function startPairing(entryId, gatewaySn) {
             if (!confirm('确定要启动网关配对模式吗？\n配对期间请将子设备靠近网关。')) return;
             const statusEl = document.getElementById('gw-status-' + entryId);
             updateGatewayStatus(statusEl, 'pairing');
             try {
                 const resp = await haApi('/config/device_registry?config_entry_id=' + entryId);
                 if (!resp.ok) throw new Error('HA API ' + resp.status);
                 const devices = await resp.json();
                 const gwDevice = devices.find(d => !d.via_device_id);
                 if (!gwDevice) { showToast('未找到网关设备', 'err'); return; }
                 const pairResp = await haApi('/services/window_controller_gateway/start_pairing', 'POST', {
                     device_id: gwDevice.id, duration: 60
                 });
                 if (!pairResp.ok) throw new Error('HA API ' + pairResp.status);
                 showToast('配对模式已启动（60秒），请操作子设备', 'ok');
                 setTimeout(() => loadGatewayDevices(entryId, gatewaySn), 10000);
                 setTimeout(() => loadGatewayDevices(entryId, gatewaySn), 60000);
             } catch (e) {
                 showToast('配对启动失败: ' + e.message, 'err');
                 updateGatewayStatus(statusEl, 'online');
             }
         }

         async function controlDevice(deviceId, command, entryId) {
             showToast('正在发送命令: ' + command + '...', 'warn');
             try {
                 const resp = await haApi('/states');
                 if (!resp.ok) throw new Error('HA API ' + resp.status);
                 const states = await resp.json();
                 const devResp = await haApi('/config/device_registry?config_entry_id=' + entryId);
                 if (!devResp.ok) throw new Error('HA API ' + devResp.status);
                 const devices = await devResp.json();
                 const dev = devices.find(d => d.id === deviceId);
                 let sn = '';
                 if (dev && dev.identifiers && dev.identifiers.length > 0) {
                     const ident = dev.identifiers[0];
                     if (Array.isArray(ident) && ident.length > 1) sn = ident[1];
                 }
                 const snSuffix = sn.slice(-6).toLowerCase();
                 const coverEntity = states.find(s =>
                     s.entity_id.startsWith('cover.') && s.entity_id.toLowerCase().includes(snSuffix)
                 );
                 if (coverEntity) {
                     let service = '';
                     if (command === 'open') service = 'open_cover';
                     else if (command === 'close') service = 'close_cover';
                     else if (command === 'stop') service = 'stop_cover';
                     if (service) {
                         const r = await haApi('/services/cover/' + service, 'POST', { entity_id: coverEntity.entity_id });
                         if (!r.ok) throw new Error('HA API ' + r.status);
                         showToast('命令已发送: ' + command, 'ok');
                     } else if (command === 'wind_lock_tilt' || command === 'wind_lock_flat') {
                         const btnSuffix = command === 'wind_lock_tilt' ? 'wind_lock_tilt' : 'wind_lock_flat';
                         const btnEntity = states.find(s =>
                             s.entity_id.startsWith('button.') &&
                             s.entity_id.toLowerCase().includes(snSuffix) &&
                             s.entity_id.includes(btnSuffix)
                         );
                         if (btnEntity) {
                             const r = await haApi('/services/button/press', 'POST', { entity_id: btnEntity.entity_id });
                             if (!r.ok) throw new Error('HA API ' + r.status);
                             showToast('模式切换: ' + (command === 'wind_lock_tilt' ? '内倒' : '平开'), 'ok');
                         } else {
                             showToast('未找到模式按钮实体', 'warn');
                         }
                     }
                 } else {
                     showToast('未找到设备 cover 实体', 'warn');
                 }
                 setTimeout(() => loadGatewayDevices(entryId, ''), 2000);
             } catch (e) {
                 showToast('控制失败: ' + e.message, 'err');
             }
         }

         async function controlDevicePosition(deviceId, position, entryId) {
             try {
                 const resp = await haApi('/states');
                 if (!resp.ok) throw new Error('HA API ' + resp.status);
                 const states = await resp.json();
                 const devResp = await haApi('/config/device_registry?config_entry_id=' + entryId);
                 if (!devResp.ok) throw new Error('HA API ' + devResp.status);
                 const devices = await devResp.json();
                 const dev = devices.find(d => d.id === deviceId);
                 let sn = '';
                 if (dev && dev.identifiers && dev.identifiers.length > 0) {
                     const ident = dev.identifiers[0];
                     if (Array.isArray(ident) && ident.length > 1) sn = ident[1];
                 }
                 const snSuffix = sn.slice(-6).toLowerCase();
                 const coverEntity = states.find(s =>
                     s.entity_id.startsWith('cover.') && s.entity_id.toLowerCase().includes(snSuffix)
                 );
                 if (coverEntity) {
                     const r = await haApi('/services/cover/set_cover_position', 'POST', {
                         entity_id: coverEntity.entity_id, position: parseInt(position)
                     });
                     if (!r.ok) throw new Error('HA API ' + r.status);
                     showToast('位置设置: ' + position + '%', 'ok');
                 } else {
                     showToast('未找到设备 cover 实体', 'warn');
                 }
             } catch (e) {
                 showToast('位置设置失败: ' + e.message, 'err');
             }
         }

         // ========== 检查更新 ==========
         async function checkForUpdates() {
             const card = document.getElementById('updateCard');
             const content = document.getElementById('updateContent');
             card.style.display = 'block';
             content.innerHTML = '<div class="loading"><div class="spinner"></div><p>正在检查更新...</p></div>';
             try {
                 // 使用 nginx 代理访问 GitHub API，避免 Ingress iframe CSP 拦截外部请求
                 const resp = await fetch('/api/github/repos/fangwenyi-dev/ha-gateway-plugin/releases/latest');
                 if (!resp.ok) throw new Error('GitHub API 不可用 (HTTP ' + resp.status + ')');
                 const release = await resp.json();
                 const latestVersion = release.tag_name.replace(/^v/, '');
                 const hasUpdate = compareVersions(latestVersion, CURRENT_VERSION) > 0;
                 if (hasUpdate) {
                     const body = release.body || '暂无变更日志';
                     const truncatedBody = body.length > 800 ? body.substring(0, 800) + '...' : body;
                     content.innerHTML = '<div class="update-box"><div class="update-info">' +
                         '<div class="update-title">发现新版本 v' + escapeHtml(latestVersion) + '</div>' +
                         '<div class="update-desc">当前版本 v' + CURRENT_VERSION + '</div></div>' +
                         '<button class="btn btn-success" onclick="doUpgrade()">一键升级</button>' +
                         '<a class="btn btn-primary" href="' + escapeHtml(release.html_url) + '" target="_blank">查看详情</a></div>' +
                         '<div style="margin-top:10px;font-size:12px;color:var(--text-muted);white-space:pre-wrap;">' + escapeHtml(truncatedBody) + '</div>';
                 } else {
                     content.innerHTML = '<div class="update-box" style="background:linear-gradient(135deg,var(--green-bg),#d1fae5);"><div class="update-info">' +
                         '<div class="update-title" style="color:#065f46;">已是最新版本 v' + CURRENT_VERSION + '</div>' +
                         '<div class="update-desc">GitHub 最新版本: v' + escapeHtml(latestVersion) + '</div></div></div>';
                 }
             } catch (e) {
                 content.innerHTML = '<div class="update-box" style="background:var(--red-bg);"><div class="update-info">' +
                     '<div class="update-title" style="color:#991b1b;">检查更新失败</div>' +
                     '<div class="update-desc">' + escapeHtml(e.message) + '</div></div></div>';
             }
         }

         // ========== 一键升级 ==========
         async function doUpgrade() {
             if (!confirm('确定要一键升级插件吗？\n\n升级过程：\n1. 调用 HA Supervisor 更新插件\n2. 更新完成后需重启插件\n3. 重启后自动安装最新集成代码\n\n升级期间插件会短暂不可用。')) return;
             showToast('正在执行一键升级...', 'warn');
             try {
                 // 调用 Supervisor API 更新插件
                 // POST /supervisor/addons/{slug}/update — 拉取最新镜像并更新
                 // 通过 nginx /api/supervisor/ 代理，token 已在 Nginx 层注入
                 const resp = await fetch('/api/supervisor/addons/huijian_mqtt_broker/update', {
                     method: 'POST',
                     headers: { 'Content-Type': 'application/json' }
                 });
                 const data = await resp.json().catch(() => ({}));
                 if (resp.ok && data.result === 'ok') {
                     showToast('升级命令已发送，插件正在更新中...', 'ok');
                     setTimeout(() => { window.location.reload(); }, 8000);
                 } else if (resp.status === 400 && data.message && data.message.includes('already')) {
                     showToast('插件已是最新版本，无需升级', 'warn');
                 } else {
                     showToast('升级失败: ' + (data.message || 'HTTP ' + resp.status), 'err');
                 }
             } catch (e) {
                 showToast('升级请求失败: ' + e.message, 'err');
             }
         }

         // ========== 工具函数 ==========
         function compareVersions(v1, v2) {
             const parts1 = v1.split('.').map(Number);
             const parts2 = v2.split('.').map(Number);
             for (let i = 0; i < Math.max(parts1.length, parts2.length); i++) {
                 const p1 = parts1[i] || 0, p2 = parts2[i] || 0;
                 if (p1 > p2) return 1;
                 if (p1 < p2) return -1;
             }
             return 0;
         }

         function escapeHtml(text) {
             if (text === null || text === undefined) return '';
             const div = document.createElement('div');
             div.textContent = String(text);
             return div.innerHTML;
         }

         function showToast(message, type) {
             const toast = document.createElement('div');
             toast.className = 'toast toast-' + (type || 'ok');
             toast.textContent = message;
             document.body.appendChild(toast);
             setTimeout(() => {
                 toast.style.opacity = '0';
                 toast.style.transition = 'opacity 0.3s';
                 setTimeout(() => toast.remove(), 300);
             }, 3000);
         }

         // ========== 启动 ==========
         init();
         setInterval(refreshAll, 30000);
