    # 从上下文中获取网关SN和名称（如果是从发现流程进入）
    gateway_sn_from_context = self.context.get("gateway_sn")
    gateway_name_from_context = self.context.get("gateway_name")

    if user_input is not None:
        gateway_sn = user_input[CONF_GATEWAY_SN].strip()
        gateway_name = user_input.get(CONF_GATEWAY_NAME, "").strip() or f"{DEFAULT_GATEWAY_NAME} {gateway_sn[-4:]}"

        # Validate gateway SN
        if not validate_gateway_sn(gateway_sn):
            errors[CONF_GATEWAY_SN] = "invalid_sn_format"
        else:
            # Check if already configured
            # unique_id 统一小写：HA 的 config entry unique_id 比较大小写敏感，
            # 而集成其他模块均按小写比较，避免同一网关不同大小写重复添加
            await self.async_set_unique_id(gateway_sn.lower())
            self._abort_if_unique_id_configured()
            # 兜底：历史 entry 的 unique_id 可能为旧版输入原样（大小写敏感），
            # 精确匹配会漏判，此处按 data 中的网关 SN 小写遍历补一次检查
            for entry in self.hass.config_entries.async_entries(DOMAIN):
                if entry.data.get(CONF_GATEWAY_SN, "").lower() == gateway_sn.lower():
                    return self.async_abort(reason="already_configured")

            # 测试网关连接性
            try:
                # 一体化插件：若存在引导标记且尚无 MQTT 条目，先自动创建
                try:
                    await ensure_mqtt_connection(self.hass)
                except ConfigEntryNotReady:
                    errors["base"] = "mqtt_not_available"

                # MQTT 集成未启用是硬性前置条件，直接报错（不可跳过）
                if not self.hass.data.get("mqtt"):
                    errors["base"] = "mqtt_not_available"
                else:
                    connected = await self._test_gateway_connectivity(gateway_sn)
                    if not connected:
                        # 未在测试窗口内收到网关上报：不阻塞添加。
                        # 网关可能未上电/未连 MQTT/上报间隔较长，
                        # 进入确认步骤让用户决定是否仍然添加。
                        self._pending_gateway_sn = gateway_sn
                        self._pending_gateway_name = gateway_name
                        return await self.async_step_confirm_add()
            except Exception:
                errors["base"] = "cannot_connect"

            if not errors:
                # 创建配置条目
                return self.async_create_entry(
                    title=gateway_name,
                    data={
                        CONF_GATEWAY_SN: gateway_sn,
                        CONF_GATEWAY_NAME: gateway_name
                    }
                )

    # Configuration form
    default_sn = gateway_sn_from_context or (user_input.get(CONF_GATEWAY_SN, "") if user_input else "")
    if default_sn:
        default_name = gateway_name_from_context or (user_input.get(CONF_GATEWAY_NAME, f"{DEFAULT_GATEWAY_NAME} {default_sn[-4:]}") if user_input else f"{DEFAULT_GATEWAY_NAME} {default_sn[-4:]}")
    else:
        default_name = gateway_name_from_context or (user_input.get(CONF_GATEWAY_NAME, DEFAULT_GATEWAY_NAME) if user_input else DEFAULT_GATEWAY_NAME)

    data_schema = vol.Schema({
        vol.Required(
            CONF_GATEWAY_SN,
            default=default_sn
        ): str,
        vol.Optional(
            CONF_GATEWAY_NAME,
            description={"suggested_value": default_name},
            default=default_name
        ): str,
    })

    return self.async_show_form(
        step_id="user",
        data_schema=data_schema,
        errors=errors,
        description_placeholders={
            "example_sn": "100121501186",
            "min_length": "10"
        }
    )

async def async_step_confirm_add(self, user_input: Optional[Dict[str, Any]] = None) -> FlowResult:
    """连接测试未通过时的确认步骤：允许用户仍然添加网关

    本集成无法主动探测网关（协议规定网关只能主动上报），

    except ConfigEntryNotReady:
        # 不二次包装：保留原始 ConfigEntryNotReady 的可重试提示信息（HA 会展示给用户）
        # 清理 debug_logging 引用计数，避免失败 entry 永久占用 DEBUG 级别
        _debug_logging_entries.discard(entry.entry_id)
        if not _debug_logging_entries:
            _LOGGER.setLevel(logging.NOTSET)
        await _cleanup_partial_setup(mqtt_handler, device_manager, unsub_listeners)
        # 清理残留的 entry 数据，避免重试时读到脏状态
        hass.data[DOMAIN].pop(entry.entry_id, None)
        _LOGGER.warning("设置网关 [%s] 失败（可重试），已清理部分初始化资源", gateway_name)
        raise
    except Exception as e:
        _LOGGER.error("设置网关 [%s] 过程中失败: %s", gateway_name, e, exc_info=True)
        # 清理 debug_logging 引用计数，避免失败 entry 永久占用 DEBUG 级别
        _debug_logging_entries.discard(entry.entry_id)
        if not _debug_logging_entries:
            _LOGGER.setLevel(logging.NOTSET)
        await _cleanup_partial_setup(mqtt_handler, device_manager, unsub_listeners)
        # 清理残留的 entry 数据，避免后续操作读到已清理的 manager 引用
        hass.data[DOMAIN].pop(entry.entry_id, None)
        return False

async def _cleanup_partial_setup(mqtt_handler, device_manager, unsub_listeners) -> None:
    """清理 async_setup_entry 中途失败时已创建的部分资源（幂等，各步骤独立容错）"""
    if mqtt_handler:
        try:
            await mqtt_handler.cleanup()
        except Exception as e:
            _LOGGER.debug("清理MQTT处理器异常: %s", e)
    if device_manager and hasattr(device_manager, 'cleanup'):
        try:
            await device_manager.cleanup()
        except Exception as e:
            _LOGGER.debug("清理设备管理器异常: %s", e)
    for unsub in (unsub_listeners or []):
        try:
            unsub()
        except Exception as e:
            _LOGGER.debug("取消监听器异常: %s", e)

async def async_unload_entry(hass: HomeAssistant, entry: ConfigEntry) -> bool:
    """卸载配置条目"""
    entry_id = entry.entry_id
    _LOGGER.info("正在卸载配置条目: %s", entry_id)

