     <meta charset="UTF-8">
     <meta name="viewport" content="width=device-width, initial-scale=1.0">
     <title>慧尖 LoRa 网关</title>
     <style>
         :root {
             --primary: #5b6ee1;
             --primary-dark: #4451b5;
             --primary-light: #818cf8;
             --bg: #f5f6fa;
             --card-bg: #ffffff;
             --text: #1a1a2e;
             --text-muted: #6b7280;
             --border: #e5e7eb;
             --green: #10b981;
             --green-bg: #ecfdf5;
             --red: #ef4444;
             --red-bg: #fef2f2;
             --yellow: #f59e0b;
             --yellow-bg: #fffbeb;
             --blue: #3b82f6;
             --blue-bg: #eff6ff;
             --radius: 12px;
             --shadow: 0 1px 3px rgba(0,0,0,0.06), 0 1px 2px rgba(0,0,0,0.04);
             --shadow-md: 0 4px 6px -1px rgba(0,0,0,0.08), 0 2px 4px -1px rgba(0,0,0,0.04);
         }
         * { margin: 0; padding: 0; box-sizing: border-box; }
         body {
             font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", sans-serif;
             background: var(--bg); color: var(--text); padding: 12px; max-width: 860px; margin: 0 auto;
             -webkit-font-smoothing: antialiased;
         }
         /* ===== Header ===== */
         .header {
             background: linear-gradient(135deg, var(--primary) 0%, var(--primary-dark) 100%);
             color: white; padding: 20px 24px; border-radius: var(--radius); margin-bottom: 12px;
             display: flex; justify-content: space-between; align-items: center;
             box-shadow: var(--shadow-md);
         }
         .header h1 { font-size: 20px; font-weight: 700; }
         .header .ver { font-size: 11px; opacity: 0.75; margin-top: 2px; }
         .header .actions { display: flex; gap: 6px; }
         .btn {
             padding: 7px 16px; border-radius: 8px; border: none; font-size: 13px;
             cursor: pointer; font-weight: 600; transition: all .15s; display: inline-flex;
             align-items: center; gap: 4px;
         }
         .btn-primary { background: white; color: var(--primary); }
         .btn-primary:hover { background: #f0f0ff; }
         .btn-success { background: var(--green); color: white; }
         .btn-success:hover { background: #059669; }
         .btn-danger { background: var(--red); color: white; }
         .btn-danger:hover { background: #dc2626; }
         .btn-warn { background: var(--yellow); color: white; }
         .btn-warn:hover { background: #d97706; }
         .btn-sm { padding: 5px 12px; font-size: 12px; }
         .btn:disabled { opacity: 0.4; cursor: not-allowed; }
         /* ===== Card ===== */
         .card {
             background: var(--card-bg); border-radius: var(--radius); padding: 16px 18px;
             box-shadow: var(--shadow); margin-bottom: 12px;
         }
         .card-title {
             font-size: 13px; font-weight: 700; color: var(--text-muted); margin-bottom: 14px;
             display: flex; align-items: center; gap: 6px;
         }
         /* ===== Status Grid ===== */
         .status-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; }
         .status-item {
             display: flex; flex-direction: column; align-items: center; text-align: center;
             padding: 14px 8px; border-radius: 10px; background: var(--bg); transition: all .2s;
         }
         .status-item .dot { width: 10px; height: 10px; border-radius: 50%; margin-bottom: 8px; }
         .dot-ok { background: var(--green); box-shadow: 0 0 0 3px var(--green-bg); }
         .dot-err { background: var(--red); box-shadow: 0 0 0 3px var(--red-bg); }
         .dot-warn { background: var(--yellow); box-shadow: 0 0 0 3px var(--yellow-bg); }
         .status-item .label { font-size: 11px; color: var(--text-muted); margin-bottom: 2px; }
         .status-item .value { font-size: 13px; font-weight: 700; }
         /* ===== Gateway ===== */
         .gateway-item {
             border: 1px solid var(--border); border-radius: 10px; padding: 14px; margin-bottom: 10px;
             transition: border-color .2s;
         }
         .gateway-item:hover { border-color: var(--primary-light); }
         .gateway-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 10px; }
         .gateway-name { font-size: 15px; font-weight: 700; }
         .gateway-sn { font-size: 11px; color: var(--text-muted); margin-left: 8px; }
         .device-list { margin-top: 8px; }
         .device-item {
             display: flex; align-items: center; justify-content: space-between;
             padding: 10px 12px; border-radius: 8px; background: var(--bg);
             margin-bottom: 6px; flex-wrap: wrap; gap: 8px; transition: background .15s;
         }
         .device-item:hover { background: #eef0f4; }
         .device-info { flex: 1; min-width: 100px; }
         .device-name { font-size: 13px; font-weight: 600; }
         .device-sn { font-size: 10px; color: var(--text-muted); }
         .device-status { font-size: 11px; margin-top: 3px; color: var(--text-muted); }
         .device-controls { display: flex; gap: 4px; flex-wrap: wrap; align-items: center; }
         .position-slider { width: 90px; height: 22px; }
         /* ===== Badge ===== */
         .badge {
             display: inline-flex; align-items: center; padding: 3px 10px; border-radius: 20px;
             font-size: 11px; font-weight: 600;
         }
         .badge-ok { background: var(--green-bg); color: #065f46; }
         .badge-warn { background: var(--yellow-bg); color: #92400e; }
         .badge-err { background: var(--red-bg); color: #991b1b; }
         .badge-info { background: var(--blue-bg); color: #1e40af; }
         .badge-gray { background: #f3f4f6; color: #6b7280; }
         /* ===== Update ===== */
         .update-box {
             background: linear-gradient(135deg, var(--blue-bg) 0%, #dbeafe 100%);
             border-radius: 10px; padding: 16px; margin-top: 10px;
             display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 8px;
         }
         .update-info { flex: 1; min-width: 200px; }
         .update-title { font-size: 14px; font-weight: 700; color: var(--blue); }
         .update-desc { font-size: 12px; color: var(--text-muted); margin-top: 4px; }
         /* ===== Misc ===== */
         .loading { text-align: center; padding: 20px; color: var(--text-muted); }
         .spinner {
             display: inline-block; width: 24px; height: 24px;
             border: 3px solid var(--border); border-top: 3px solid var(--primary);
             border-radius: 50%; animation: spin 0.8s linear infinite;
         }
         @keyframes spin { to { transform: rotate(360deg); } }
         .toast {
             position: fixed; bottom: 24px; right: 24px; padding: 12px 20px;
             border-radius: 10px; color: white; font-size: 13px; z-index: 9999;
             animation: slideIn .3s ease; max-width: 360px; box-shadow: var(--shadow-md);
         }
         @keyframes slideIn { from { transform: translateX(400px); opacity: 0; } to { transform: translateX(0); opacity: 1; } }
         .toast-ok { background: var(--green); }
         .toast-err { background: var(--red); }
         .toast-warn { background: var(--yellow); }
         .info-box { background: var(--blue-bg); border-left: 4px solid var(--blue); padding: 12px; border-radius: 8px; margin-top: 10px; }
         .info-box h3 { font-size: 12px; color: var(--blue); margin-bottom: 6px; font-weight: 700; }
         .info-box p { font-size: 12px; color: var(--text-muted); line-height: 1.6; }
         .info-box code {
             background: white; padding: 2px 6px; border-radius: 4px;
             font-family: "SF Mono", Consolas, monospace; font-size: 11px; color: var(--text);
         }
         .footer { text-align: center; padding: 16px; color: #b0b0b0; font-size: 11px; }
         .empty-state { text-align: center; padding: 30px; color: var(--text-muted); }
         .empty-state .icon { font-size: 36px; margin-bottom: 8px; }
         .empty-state .hint { font-size: 12px; margin-top: 8px; }
         @media (max-width: 520px) {
             .status-grid { grid-template-columns: 1fr; }
         }
     </style>
 </head>
