# 此文件为镜像构建时的默认配置
# run.sh 启动时会动态重新生成此文件（注入 SUPERVISOR_TOKEN 和端口变量）
# 如果 run.sh 未正确执行（如调试模式），此配置可用作兜底
server {
    listen 8099;

    # 安全: 仅允许 HA Core (172.30.32.2) 访问 Ingress 端口
    allow 172.30.32.2;
    deny all;

    location / {
        root /usr/share/nginx/html;
        index index.html;
        try_files $uri $uri/ /index.html;
    }

    # 代理 HA Core REST API — token 在 run.sh 启动时注入
    # /api/ha/ → HA Core REST API（设备、服务、实体等）
    location /api/ha/ {
        proxy_pass http://supervisor/core/api/;
        proxy_set_header Authorization "Bearer DYNAMIC_TOKEN";
        proxy_set_header Content-Type "application/json";
        proxy_set_header Accept "application/json";
        proxy_read_timeout 30s;
        proxy_connect_timeout 5s;
        proxy_ssl_verify off;
    }

    # /api/supervisor/ → Supervisor API（插件更新、重启等）
    location /api/supervisor/ {
        proxy_pass http://supervisor/supervisor/;
        proxy_set_header Authorization "Bearer DYNAMIC_TOKEN";
        proxy_set_header Content-Type "application/json";
        proxy_set_header Accept "application/json";
        proxy_read_timeout 120s;
        proxy_connect_timeout 5s;
        proxy_ssl_verify off;
    }

    # MQTT Broker 状态检测 — nginx 直接返回，无需调用 HA API
    location /api/status {
        add_header Content-Type application/json always;
        return 200 '{"status":"running","broker":"mosquitto","port":2022,"internal_port":2022}';
    }

    location /api/version {
        add_header Content-Type application/json;
        root /usr/share/nginx/html;
        try_files /version.json =404;
    }

    # 集成安装状态 — 插件本地事实（integration.json 由 run.sh 写入）
    location = /api/integration {
        add_header Content-Type application/json always;
        root /usr/share/nginx/html;
        try_files /integration.json =404;
    }

    # Broker 客户端连接数 — broker_status.json 由后台循环每 10 秒刷新
    location = /api/broker {
        add_header Content-Type application/json always;
        root /usr/share/nginx/html;
        try_files /broker_status.json =404;
    }

    # 代理 GitHub API（检查更新用），避免 Ingress iframe 中 CSP 拦截外部请求
    location /api/github/ {
        proxy_pass https://api.github.com/;
        proxy_set_header Host api.github.com;
        proxy_ssl_server_name on;
        proxy_read_timeout 15s;
        proxy_connect_timeout 10s;
    }
}

