+                s.entity_id.includes('online')
+            ) : null;
+            // 电池电压: sensor.*{sn_suffix}*voltage* 或 sensor.*{sn_suffix}*battery*
+            const batteryEntity = snSuffix ? states.find(s =>
+                s.entity_id.startsWith('sensor.') && s.entity_id.toLowerCase().includes(snSuffix) &&
+                (s.entity_id.includes('voltage') || s.entity_id.includes('battery'))
+            ) : null;
+            // 开窗速度/力度: number.*{sn_suffix}*speed* / number.*{sn_suffix}*strength*
+            const speedEntity = snSuffix ? states.find(s =>
+                s.entity_id.startsWith('number.') && s.entity_id.toLowerCase().includes(snSuffix) && s.entity_id.includes('speed')
+            ) : null;
+            const strengthEntity = snSuffix ? states.find(s =>
+                s.entity_id.startsWith('number.') && s.entity_id.toLowerCase().includes(snSuffix) && s.entity_id.includes('strength')
+            ) : null;
             // 集成未提供 current_position，实际位置属性为 attributes.position（缺失时显示 --）
             const rawPos = coverEntity ? coverEntity.attributes.position : undefined;
             const currentPos = (rawPos === undefined || rawPos === null) ? '--' : rawPos;
             const safeName = escapeHtml(devName);
             const safeSn = escapeHtml(sn);
             const safeDevId = escapeHtml(devId);
             const safeEntryId = escapeHtml(entryId);
+            // 在线圆点（无实体时默认离线红点，loadDeviceState 会再校正）
+            const isOnline = onlineEntity ? (onlineEntity.state === 'on') : false;
+            // 电池电压（sensor 优先，缺失时回退 cover attributes.voltage）
+            let batteryText = '';
+            if (batteryEntity && batteryEntity.state && batteryEntity.state !== 'unknown' && batteryEntity.state !== 'unavailable') {
+                const bUnit = batteryEntity.attributes.unit_of_measurement || 'V';
+                batteryText = batteryEntity.state + bUnit;
+            } else if (coverEntity && coverEntity.attributes.voltage) {
+                batteryText = coverEntity.attributes.voltage + 'V';
+            }
+            // 速度/力度滑块取值与范围（缺失实体时禁用）
+            const speedMin = speedEntity && speedEntity.attributes.min !== undefined ? speedEntity.attributes.min : 0;
+            const speedMax = speedEntity && speedEntity.attributes.max !== undefined ? speedEntity.attributes.max : 100;
+            const speedValid = speedEntity && speedEntity.state && speedEntity.state !== 'unknown' && speedEntity.state !== 'unavailable';
+            const speedUnit = (speedEntity && speedEntity.attributes.unit_of_measurement) || '';
+            const strengthMin = strengthEntity && strengthEntity.attributes.min !== undefined ? strengthEntity.attributes.min : 0;
+            const strengthMax = strengthEntity && strengthEntity.attributes.max !== undefined ? strengthEntity.attributes.max : 100;
+            const strengthValid = strengthEntity && strengthEntity.state && strengthEntity.state !== 'unknown' && strengthEntity.state !== 'unavailable';
+            const strengthUnit = (strengthEntity && strengthEntity.attributes.unit_of_measurement) || '';
             let controls = '<div class="device-controls">' +
                 '<button class="btn btn-success btn-sm" onclick="controlDevice(\'' + jsQuote(safeDevId) + '\',\'open\',\'' + jsQuote(safeEntryId) + '\')">开</button>' +
                 '<button class="btn btn-danger btn-sm" onclick="controlDevice(\'' + jsQuote(safeDevId) + '\',\'close\',\'' + jsQuote(safeEntryId) + '\')">关</button>' +
                 '<button class="btn btn-warn btn-sm" onclick="controlDevice(\'' + jsQuote(safeDevId) + '\',\'stop\',\'' + jsQuote(safeEntryId) + '\')">停</button>' +
                 '<input type="range" class="position-slider" min="0" max="100" value="' + (currentPos === '--' ? 0 : currentPos) + '"' +
                 ' oninput="this.nextElementSibling.textContent=this.value+\'%\'"' +
                 ' onchange="controlDevicePosition(\'' + jsQuote(safeDevId) + '\', this.value, \'' + jsQuote(safeEntryId) + '\')">' +
-                '<span style="font-size:11px;min-width:30px;">' + currentPos + (currentPos === '--' ? '' : '%') + '</span></div>';
+                '<span style="font-size:11px;min-width:30px;">' + currentPos + (currentPos === '--' ? '' : '%') + '</span>' +
+                '<button class="btn btn-danger btn-sm" style="margin-left:4px;" title="移除设备" onclick="controlDevice(\'' + jsQuote(safeDevId) + '\',\'remove\',\'' + jsQuote(safeEntryId) + '\')">移除</button></div>';
+            // 速度 / 力度滑块
+            controls += '<div class="device-controls" style="margin-top:4px;">' +
+                '<span class="slider-label">速度</span>' +
+                '<input type="range" class="speed-slider" min="' + speedMin + '" max="' + speedMax + '" value="' + (speedValid ? speedEntity.state : speedMin) + '"' +
+                (speedEntity ? '' : ' disabled') +
+                ' oninput="this.nextElementSibling.textContent=this.value' + (speedUnit ? '+\'' + speedUnit + '\'' : '') + '"' +
+                ' onchange="controlDevice(\'' + jsQuote(safeDevId) + '\',\'set_speed\',\'' + jsQuote(safeEntryId) + '\', this.value)">' +
+                '<span class="slider-value speed-value">' + (speedValid ? speedEntity.state + speedUnit : '--') + '</span>' +
+                '<span class="slider-label" style="margin-left:8px;">力度</span>' +
+                '<input type="range" class="strength-slider" min="' + strengthMin + '" max="' + strengthMax + '" value="' + (strengthValid ? strengthEntity.state : strengthMin) + '"' +
+                (strengthEntity ? '' : ' disabled') +
+                ' oninput="this.nextElementSibling.textContent=this.value' + (strengthUnit ? '+\'' + strengthUnit + '\'' : '') + '"' +
+                ' onchange="controlDevice(\'' + jsQuote(safeDevId) + '\',\'set_strength\',\'' + jsQuote(safeEntryId) + '\', this.value)">' +
+                '<span class="slider-value strength-value">' + (strengthValid ? strengthEntity.state + strengthUnit : '--') + '</span></div>';
             if (supportsWindLock) {
                 controls += '<div class="device-controls" style="margin-top:4px;">' +
                     '<button class="btn btn-sm" style="background:#607d8b;color:white;" onclick="controlDevice(\'' + jsQuote(safeDevId) + '\',\'wind_lock_tilt\',\'' + jsQuote(safeEntryId) + '\')">内倒</button>' +
                     '<button class="btn btn-sm" style="background:#78909c;color:white;" onclick="controlDevice(\'' + jsQuote(safeDevId) + '\',\'wind_lock_flat\',\'' + jsQuote(safeEntryId) + '\')">平开</button>' +
                     '</div>';
             }
             return '<div class="device-item" id="dev-' + safeDevId + '">' +
-                '<div class="device-info"><div class="device-name">' + safeName + '</div>' +
+                '<div class="device-info"><div class="device-name dev-name">' +
+                '<span class="dev-dot ' + (isOnline ? 'dot-online' : 'dot-offline') + '" id="dev-dot-' + safeDevId + '"></span>' +
+                safeName + '</div>' +
                 '<div class="device-sn">SN: ' + safeSn + '</div>' +
-                '<div class="device-status" id="dev-state-' + safeDevId + '">状态: 加载中</div></div>' +
+                '<div class="device-status" id="dev-state-' + safeDevId + '">状态: 加载中' + (batteryText ? ' | 电压: ' + batteryText : '') + '</div></div>' +
                 controls + '</div>';
