         // ========== 检查更新 ==========
         async function checkForUpdates() {
             const card = document.getElementById('updateCard');
             const content = document.getElementById('updateContent');
             card.style.display = 'block';
             content.innerHTML = '<div class="loading"><div class="spinner"></div><p>正在检查更新...</p></div>';
             try {
                 // 使用 nginx 代理访问 GitHub API，避免 Ingress iframe CSP 拦截外部请求
                 const resp = await fetch(INGRESS_BASE + 'api/github/repos/fangwenyi-dev/ha-gateway-plugin/releases/latest');
                 if (!resp.ok) throw new Error('GitHub API 不可用 (HTTP ' + resp.status + ')');
                 const release = await resp.json();
                 const latestVersion = release.tag_name.replace(/^v/, '');
                 const hasUpdate = compareVersions(latestVersion, CURRENT_VERSION) > 0;
                 if (hasUpdate) {
                     const body = release.body || '暂无变更日志';
                     const truncatedBody = body.length > 800 ? body.substring(0, 800) + '...' : body;
                     content.innerHTML = '<div class="update-box"><div class="update-info">' +
                         '<div class="update-title">发现新版本 v' + escapeHtml(latestVersion) + '</div>' +
                         '<div class="update-desc">当前版本 v' + CURRENT_VERSION + '</div></div>' +
                         '<button class="btn btn-success" onclick="doUpgrade()">一键升级</button>' +
                         '<a class="btn btn-primary" href="' + escapeHtml(release.html_url) + '" target="_blank">查看详情</a></div>' +
                         '<div style="margin-top:10px;font-size:12px;color:var(--text-muted);white-space:pre-wrap;">' + escapeHtml(truncatedBody) + '</div>';
                 } else {
                     content.innerHTML = '<div class="update-box" style="background:linear-gradient(135deg,var(--green-bg),#d1fae5);"><div class="update-info">' +
                         '<div class="update-title" style="color:#065f46;">已是最新版本 v' + CURRENT_VERSION + '</div>' +
                         '<div class="update-desc">GitHub 最新版本: v' + escapeHtml(latestVersion) + '</div></div></div>';
                 }
             } catch (e) {
                 content.innerHTML = '<div class="update-box" style="background:var(--red-bg);"><div class="update-info">' +
                     '<div class="update-title" style="color:#991b1b;">检查更新失败</div>' +
                     '<div class="update-desc">' + escapeHtml(e.message) + '</div></div></div>';
             }
         }

         // ========== 一键升级 ==========
         async function doUpgrade() {
             if (!confirm('确定要一键升级插件吗？\n\n升级过程：\n1. 调用 HA Supervisor 更新插件\n2. 更新完成后需重启插件\n3. 重启后自动安装最新集成代码\n\n升级期间插件会短暂不可用。')) return;
             showToast('正在执行一键升级...', 'warn');
             try {
                 // 使用 /addons/self/update（免 admin 权限路径，Supervisor 自动识别调用者）
                 // 原用 /addons/{slug}/update 需要 hassio_api: true + admin 角色，addon token 无权限返回 403
                 const resp = await fetch(INGRESS_BASE + 'api/supervisor/addons/self/update', {
                     method: 'POST',
                     headers: { 'Content-Type': 'application/json' },
                     body: JSON.stringify({ backup: false })
                 });
                 const data = await resp.json().catch(() => ({}));
                 const msg = data.message || '';
                 if (resp.ok && data.result === 'ok') {
                     showToast('升级完成，正在刷新…', 'ok');
                     setTimeout(() => { window.location.reload(); }, 1500);
                 } else if (/already.*(latest|up.to.date)|nothing to do/i.test(msg)) {
                     showToast('已是最新版本', 'warn');
                 } else if (/job.*running|in progress|another (update|job)/i.test(msg)) {
                     showToast('已有任务进行中，请稍后再试', 'warn');
                 } else if (/abort/i.test(msg)) {
                     showToast('升级已中止', 'warn');
                 } else {
                     showToast('升级失败: ' + (msg || 'HTTP ' + resp.status), 'err');
                 }
             } catch (e) {
                 showToast('升级请求失败: ' + e.message, 'err');
             }
         }

         // ========== 工具函数 ==========
         function compareVersions(v1, v2) {
             const parts1 = v1.split('.').map(Number);
             const parts2 = v2.split('.').map(Number);
             for (let i = 0; i < Math.max(parts1.length, parts2.length); i++) {
                 const p1 = parts1[i] || 0, p2 = parts2[i] || 0;
                 if (p1 > p2) return 1;
                 if (p1 < p2) return -1;
             }
             return 0;
         }

         function escapeHtml(text) {
             if (text === null || text === undefined) return '';
             return String(text).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
         }

         // HTML 解析器会在 JS 编译前解码 &#39;，实体转义保护不了单引号包裹的 onclick/onchange 参数，需额外转义
         function jsQuote(v) {
             return String(v == null ? '' : v).replace(/\\/g, '\\\\').replace(/'/g, "\\'");
         }

         function showToast(message, type) {
             const toast = document.createElement('div');
             toast.className = 'toast toast-' + (type || 'ok');
             toast.textContent = message;
             document.body.appendChild(toast);
             setTimeout(() => {
                 toast.style.opacity = '0';
                 toast.style.transition = 'opacity 0.3s';
                 setTimeout(() => toast.remove(), 300);
             }, 3000);
         }

         // ========== 启动 ==========
         init();
         setInterval(refreshAll, 30000);
     </script>
