# 获取所有CI运行
$runs = gh run list --repo fangwenyi-dev/ha-gateway-plugin --limit 10 --json databaseId,status,conclusion,headSha,createdAt 2>&1 | ConvertFrom-Json
Write-Host "=== 最近10个CI运行 ==="
