    $shortSha = $run.headSha.Substring(0, 8)
    Write-Host "Run $($run.databaseId): $($run.status) - $($run.conclusion) - $shortSha - $($run.createdAt)"
}
Write-Host ""
Write-Host "=== 检查最新提交 afc2cb1 ==="
$found = $runs | Where-Object { $_.headSha -like "afc2cb1*" }
if ($found) {
    Write-Host "找到: Run $($found.databaseId) - $($found.status) - $($found.conclusion)"
} else {
    Write-Host "未找到 afc2cb1 的CI运行，可能还在排队"
}

